import{_ as a}from"./chunks/reg_reduce_index.C0ynfEmY.js";import{_ as n,o as p,a as l,b as c}from"./app.DKoEZOcr.js";const t="/ascendc.github.io/pr/5487/assets/reg_reduce_sum.Dlsxe3wb.png",_=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Reg矢量计算","link":"/api/SIMD-API/basic_api/reg_vector_compute/reg_vector_compute"},{"text":"归约计算","link":"/api/SIMD-API/basic_api/reg_vector_compute/reduction_compute/reduction_compute"},{"text":"Reduce","link":"/api/SIMD-API/basic_api/reg_vector_compute/reduction_compute/Reduce"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/reg_vector_compute/reduction_compute/Reduce.md","filePath":"api/SIMD-API/basic_api/reg_vector_compute/reduction_compute/Reduce.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"关键特性","slug":"关键特性","link":"#关键特性"},{"level":3,"title":"索引值需要强制类型转换","slug":"索引值需要强制类型转换","link":"#索引值需要强制类型转换"},{"level":3,"title":"ReduceType::SUM累加顺序","slug":"ReduceType::SUM累加顺序","link":"#ReduceType::SUM累加顺序"},{"level":3,"title":"mask为空场景及异常值处理","slug":"mask为空场景及异常值处理","link":"#mask为空场景及异常值处理"},{"level":3,"title":"提取MAX/MIN结果（值+索引）","slug":"提取MAX/MIN结果（值+索引）","link":"#提取MAX/MIN结果（值+索引）"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),e={name:"api/SIMD-API/basic_api/reg_vector_compute/reduction_compute/Reduce.md"};function d(o,s,i,r,h,g){return p(),l("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>Reduce<span id="ZH-CN_TOPIC_0000001938595870"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/reg_compute/kernel_reg_compute_vec_reduce_intf.h&quot;</code>。</p><p>归约指令根据ReduceType，将数据集合简化为单一值或者更小的集合。</p><p>ReduceType::SUM：根据mask，计算源操作数srcReg内有效元素的数据总和，将结果写入目的操作数dstReg。</p><p>ReduceType::MAX：根据mask，计算源操作数srcReg内有效元素中的最大值和索引，将结果写入目的操作数dstReg，当存在多个最大值时，会将第一个最大值的索引保存在dstReg中。</p><p>ReduceType::MIN：根据mask，计算源操作数srcReg内有效元素中的最小值和索引，将结果写入目的操作数dstReg，当存在多个最小值时，会将第一个最小值的索引保存在dstReg中。</p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">ReduceType</span><span class="w"> </span><span class="n">type</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ReduceType</span><span class="o">::</span><span class="n">SUM</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">DefaultType</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">DefaultType</span><span class="p">,</span><span class="w"> </span><span class="n">MaskMergeMode</span><span class="w"> </span><span class="n">mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MaskMergeMode</span><span class="o">::</span><span class="n">ZEROING</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">S</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">V</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Reduce</span><span class="p">(</span><span class="n">S</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">V</span><span class="w"> </span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">MaskReg</span><span class="w"> </span><span class="n">mask</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>type</td><td>ReduceType类型，支持SUM、MAX、MIN。<br>enum class ReduceType {<br> SUM = 0,<br> MAX,<br> MIN,<br>};</td></tr><tr><td>T</td><td>目的操作数dstReg的数据类型。</td></tr><tr><td>U</td><td>源操作数srcReg的数据类型。</td></tr><tr><td>mode</td><td><a href="../aux_data_types/MaskMergeMode.html">MaskMergeMode</a>，选择MERGING模式或ZEROING模式。<br>• ZEROING，mask未选中的元素在dst中置零。<br>• MERGING，当前不支持。</td></tr><tr><td>S</td><td>目的操作数的RegTensor类型，例如RegTensor&lt;half&gt;，由编译器自动推导，用户不需要填写。</td></tr><tr><td>V</td><td>源操作数的RegTensor类型，例如RegTensor&lt;half&gt;，由编译器自动推导，用户不需要填写。</td></tr></tbody></table><p><strong>表2</strong> 函数参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>dstReg</td><td>目的操作数。<br>类型为<a href="../register_data_types/RegTensor.html">RegTensor</a>。</td></tr><tr><td>srcReg</td><td>源操作数。<br>类型为<a href="../register_data_types/RegTensor.html">RegTensor</a>。</td></tr><tr><td>mask</td><td>源操作数元素操作的有效指示，详细说明请参考<a href="../register_data_types/MaskReg.html">MaskReg</a>。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p><strong>表3</strong> ReduceType::SUM数据类型支持情况</p><table><thead><tr><th>dstReg</th><th>srcReg</th></tr></thead><tbody><tr><td>half</td><td>half</td></tr><tr><td>int32_t</td><td>int16_t</td></tr><tr><td>uint32_t</td><td>uint16_t</td></tr><tr><td>int32_t</td><td>int32_t</td></tr><tr><td>uint32_t</td><td>uint32_t</td></tr><tr><td>float</td><td>float</td></tr><tr><td>int64_t</td><td>int64_t</td></tr><tr><td>uint64_t</td><td>uint64_t</td></tr></tbody></table><p><strong>表4</strong> ReduceType::MAX或ReduceType::MIN数据类型支持情况</p><table><thead><tr><th>dstReg</th><th>srcReg</th></tr></thead><tbody><tr><td>int16_t</td><td>int16_t</td></tr><tr><td>uint16_t</td><td>uint16_t</td></tr><tr><td>half</td><td>half</td></tr><tr><td>int32_t</td><td>int32_t</td></tr><tr><td>uint32_t</td><td>uint32_t</td></tr><tr><td>float</td><td>float</td></tr><tr><td>int64_t</td><td>int64_t</td></tr><tr><td>uint64_t</td><td>uint64_t</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section177921451558"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>对于归约求数据总和，mask指定源操作数是否参与计算，不参与计算的元素，被当作0进行处理。</li><li>对于归约求最大值，mask指定源操作数是否参与计算，不参与计算的元素，被当作数据类型的最小值进行处理。</li><li>对于归约求最小值，mask指定源操作数是否参与计算，不参与计算的元素，被当作数据类型的最大值进行处理。</li><li>对于归约求最大值，当所有元素均不参与计算时，将该数据类型的最小值写入dstReg，当存在多个最大值时，会将第一个最大值的索引保存在dstReg中，max(-0, +0) = +0。</li><li>对于归约求最小值，当所有元素均不参与计算时，将该数据类型的最大值写入dstReg，当存在多个最小值时，会将第一个最小值的索引保存在dstReg中，min(-0, +0) = -0。</li><li>当归约求最小值或者归约求最大值时，源操作数的数据类型和目的操作数相同。</li><li>mask为空场景及异常值处理参考<a href="#mask%E4%B8%BA%E7%A9%BA%E5%9C%BA%E6%99%AF%E5%8F%8A%E5%BC%82%E5%B8%B8%E5%80%BC%E5%A4%84%E7%90%86">mask为空场景及异常值处理</a>。</li><li>指令内累加顺序采用二叉树累加方式，规则参考<a href="#ReduceType::SUM%E7%B4%AF%E5%8A%A0%E9%A1%BA%E5%BA%8F">ReduceType::SUM累加顺序</a>。</li></ul><h2 id="关键特性">关键特性<span id="zh-cn_topic_0000002537812548_section18972943153217"></span><a class="header-anchor" href="#关键特性">​</a></h2><h3 id="索引值需要强制类型转换">索引值需要强制类型转换<a class="header-anchor" href="#索引值需要强制类型转换">​</a></h3><p>dstReg的最大值/最小值索引按照dstReg的数据类型存储，比如dstReg为half类型时，索引按照half类型存储，因此读取索引需要使用reinterpret_cast方法转换到整数类型。若数据类型是half，需要使用reinterpret_cast&lt;uint16_t*&gt;；若数据类型是float，需要使用reinterpret_cast&lt;uint32_t*&gt;。</p><p>例如，输入数据是half类型，计算结果为[1.14, 6.8e-06]，6.8e-06需要使用reinterpret_cast&lt;uint16_t*&gt;方法转换得到索引值114。转换伪代码示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">ReduceVF</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcReg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstReg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">mask</span><span class="p">;</span><span class="w">    </span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">);</span>
<span class="w">    </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">UpdateMask</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">(</span><span class="n">count</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Reduce</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">ReduceType</span><span class="o">::</span><span class="n">MAX</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span><span class="w"> </span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="p">(</span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="p">}</span><span class="w"> </span><span class="c1">// End of Vector Function</span>
</code></pre></div><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Index强制类型转换保存到Scalar，需要放Vector Function外处理</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">PIPE_V</span><span class="o">&gt;</span><span class="p">();</span><span class="w"> </span><span class="c1">// 需要插入同步，等待归约计算完后才能处理索引</span>
<span class="n">half</span><span class="w"> </span><span class="n">maxIndex</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="o">*</span><span class="p">(</span><span class="n">dstAddr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">realIndex</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="o">*</span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="kt">uint16_t</span><span class="o">*&gt;</span><span class="p">(</span><span class="o">&amp;</span><span class="n">maxIndex</span><span class="p">);</span>
</code></pre></div><p><img src="`+t+'" alt="reg_reduce_sum"></p><h3 id="ReduceType::SUM累加顺序">ReduceType::SUM累加顺序<a id="ReduceType::SUM累加顺序"></a><a class="header-anchor" href="#ReduceType::SUM累加顺序">​</a></h3><p>以二叉树累加的方式计算源操作数srcReg内有效元素的数据总和。</p><p>以half类型的数据求和为例，在srcReg内有128个数，通过二叉树的方式，两两相加，计算过程如下图所示：</p><ol><li>data1和data2相加得到data01，data3和data4相加得到data02，……，data125和data126相加得到data63，data127和data128相加得到data64；</li><li>data01和data02相加得到data001，data03和data04相加得到data002，……，data63和data64相加得到data032；</li><li>以此类推，得到目的操作数为1个half类型的数据sum。</li></ol><p><strong>图1</strong> reg_reduce_index<span id="zh-cn_topic_0000002537812548_fig1630121573314"></span><br><img src="'+a+`" alt="reg_reduce_index" title="reg_reduce_index"></p><h3 id="mask为空场景及异常值处理">mask为空场景及异常值处理<a class="header-anchor" href="#mask为空场景及异常值处理">​</a></h3><ul><li>对于归约求数据总和，当所有元素均不参与计算时，将目的操作数数据类型的0写入dstReg。</li><li>对于归约求最大值，当所有元素均不参与计算时，将该数据类型的最小值写入dstReg。</li><li>对于归约求最小值，当所有元素均不参与计算时，将该数据类型的最大值写入dstReg。</li><li>对于归约求最大值/最小值，如果输入数据存在nan，将该数据类型的nan写入dstReg，将第一个nan的索引保存在dstReg中。</li></ul><h3 id="提取MAX/MIN结果（值+索引）">提取MAX/MIN结果（值+索引）<a class="header-anchor" href="#提取MAX/MIN结果（值+索引）">​</a></h3><p>MAX/MIN归约产生两个有效结果，需要分别提取。以下示例中dstAddr为32B对齐地址，如果需要写出到非对齐地址，请参考<a href="../reg_data_store/StoreUnAlign_continuous.html">连续非对齐搬出(StoreUnAlign)</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Reduce</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">ReduceType</span><span class="o">::</span><span class="n">MAX</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">pregFull</span><span class="p">);</span>
</code></pre></div><p>方式一：整体存出后按偏移访问（最直接，适用于需要同时使用值和索引的场景）</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">pregVL2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">CreateMask</span><span class="o">&lt;</span><span class="n">T</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskPattern</span><span class="o">::</span><span class="n">VL2</span><span class="o">&gt;</span><span class="p">();</span>
<span class="c1">// 后续直接访问// dstAddr[0] -&gt; 最大值// dstAddr[1] -&gt; 最大值索引</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="p">(</span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">pregVL2</span><span class="p">);</span>
</code></pre></div><p>方式二：用Mask分离到目标地址</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">pregVL1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">CreateMask</span><span class="o">&lt;</span><span class="n">T</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskPattern</span><span class="o">::</span><span class="n">VL1</span><span class="o">&gt;</span><span class="p">();</span>
<span class="c1">// 只搬出最大值到目标地址</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="p">(</span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">pregVL1</span><span class="p">);</span>
</code></pre></div><h2 id="调用示例">调用示例<span id="section642mcpsimp"></span><a class="header-anchor" href="#调用示例">​</a></h2><ul><li><p>归约求和：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">ReduceVF</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">U</span><span class="o">*</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">,</span><span class="w"> </span>
<span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">srcRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dstRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcReg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstReg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">mask</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcAddr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">srcRepeatSize</span><span class="p">);</span>
<span class="w">        </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">UpdateMask</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;</span><span class="p">(</span><span class="n">count</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Reduce</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">ReduceType</span><span class="o">::</span><span class="n">SUM</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="p">(</span><span class="n">dstAddr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dstRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div></li><li><p>归约求最大值或者最小值：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">ReduceVF</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcReg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstReg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">mask</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcAddr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">);</span>
<span class="w">        </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">UpdateMask</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">(</span><span class="n">count</span><span class="p">);</span>
<span class="w">        </span><span class="c1">// type = ReduceType::MAX</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Reduce</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">ReduceType</span><span class="o">::</span><span class="n">MAX</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="c1">// type = ReduceType::MIN</span>
<span class="w">        </span><span class="c1">// AscendC::Reg::Reduce&lt;AscendC::Reg::ReduceType::MIN&gt;(dstReg, srcReg, mask);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="p">(</span><span class="n">dstAddr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div></li></ul></article></div>`,1)])])}const R=n(e,[["render",d]]);export{_ as __pageData,R as default};
